export type Ball = { x: number; y: number; vx: number; vy: number; r: number }

export const W = 400
export const H = 300
const R = 10
const G = 0.2

export function makeBall(): Ball {
  return {
    x: R + Math.random() * (W - 2 * R),
    y: R + Math.random() * (H - 2 * R),
    vx: (Math.random() * 2 - 1) * 4,
    vy: (Math.random() * 2 - 1) * 4,
    r: R,
  }
}

export function makeBalls(n: number): Ball[] {
  const list: Ball[] = []
  for (let i = 0; i < n; i++) list.push(makeBall())
  return list
}

export function step(balls: Ball[]): void {
  for (const b of balls) {
    b.vy += G
    b.x += b.vx
    b.y += b.vy
    if (b.x < b.r) { b.x = b.r; b.vx = Math.abs(b.vx) }
    if (b.x > W - b.r) { b.x = W - b.r; b.vx = -Math.abs(b.vx) }
    if (b.y < b.r) { b.y = b.r; b.vy = Math.abs(b.vy) }
    if (b.y > H - b.r) { b.y = H - b.r; b.vy = -Math.abs(b.vy) }
  }
  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      const a = balls[i]
      const b = balls[j]
      let dx = b.x - a.x
      let dy = b.y - a.y
      let d = Math.sqrt(dx * dx + dy * dy)
      const min = a.r + b.r
      if (d < min) {
        if (d === 0) { dx = 1; dy = 0; d = 1 }
        const nx = dx / d
        const ny = dy / d
        // separar
        const push = (min - d) / 2
        a.x -= nx * push
        a.y -= ny * push
        b.x += nx * push
        b.y += ny * push
        // intercambio de velocidades (masas iguales) solo si se acercan
        const rel = (a.vx - b.vx) * nx + (a.vy - b.vy) * ny
        if (rel > 0) {
          const tx = rel * nx
          const ty = rel * ny
          a.vx -= tx
          a.vy -= ty
          b.vx += tx
          b.vy += ty
        }
        for (const p of [a, b]) {
          p.x = Math.min(Math.max(p.x, p.r), W - p.r)
          p.y = Math.min(Math.max(p.y, p.r), H - p.r)
        }
      }
    }
  }
}

export function draw(canvas: HTMLCanvasElement, balls: Ball[]): void {
  const ctx = canvas.getContext("2d")
  if (!ctx) return
  ctx.clearRect(0, 0, W, H)
  ctx.fillStyle = "#f8fafc"
  ctx.fillRect(0, 0, W, H)
  ctx.fillStyle = "#2563eb"
  for (const b of balls) {
    ctx.beginPath()
    ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2)
    ctx.fill()
  }
}

