use "./sim.ts" { makeBall, makeBalls, step, draw }

page Home "/" {
  state count = 5
  state frames = 0
  state paused = false
  ref cv
  ref balls
  ref raf
  ref pausedFlag
  ref framesN

  fn loop() {
    if (!pausedFlag) {
      step(balls)
      draw(cv, balls)
      framesN++
      frames = framesN
    }
    raf = requestAnimationFrame(loop)
  }

  fn add() {
    balls.push(makeBall())
    count = balls.length
    draw(cv, balls)
  }

  fn toggle() {
    pausedFlag = !pausedFlag
    paused = pausedFlag
  }

  fn reset() {
    balls = makeBalls(5)
    count = 5
    framesN = 0
    frames = 0
    draw(cv, balls)
  }

  mount {
    balls = makeBalls(5)
    pausedFlag = false
    framesN = 0
    draw(cv, balls)
    raf = requestAnimationFrame(loop)
    cleanup { cancelAnimationFrame(raf) }
  }

  column gap=4 pad=4 {
    title "Simulación de pelotas"
    canvas ref=cv id="sim" width=400 height=300
    row gap=2 {
      button "Agregar" primary -> add()
      button (paused ? "Reanudar" : "Pausar") -> toggle()
      button "Reiniciar" danger -> reset()
    }
    text `Pelotas: ${count}`
    text `Cuadros: ${frames}`
  }
}

use "./sim.ts" { createSim }

page Home "/" {
  state count = 5
  state frames = 0
  state paused = false
  computed label = paused ? "Reanudar" : "Pausar"
  ref box
  ref engine

  fn add() {
    engine.add()
  }

  fn toggle() {
    if paused {
      engine.resume()
      paused = false
    } else {
      engine.pause()
      paused = true
    }
  }

  fn restart() {
    engine.reset()
    paused = false
  }

  mount {
    engine = createSim(box, (n, f) => { count = n; frames = f })
    cleanup { engine.destroy() }
  }

  column gap=4 pad=4 {
    title "Simulación de pelotas"
    canvas ref=box id="sim" width=400 height=300
    row gap=2 {
      button "Agregar" primary -> add()
      button label -> toggle()
      button "Reiniciar" -> restart()
    }
    text `Pelotas: ${count}` bold
    text `Cuadros: ${frames}`
  }
}

