interface Ball {
  x: number;
  y: number;
  vx: number;
  vy: number;
}

const W = 400;
const H = 300;
const R = 10;
const G = 0.2;

function randomBall(): Ball {
  return {
    x: R + Math.random() * (W - 2 * R),
    y: R + Math.random() * (H - 2 * R),
    vx: (Math.random() - 0.5) * 6,
    vy: (Math.random() - 0.5) * 6,
  };
}

export function createSim(
  canvas: HTMLCanvasElement,
  onUpdate: (count: number, frames: number) => void
) {
  const ctx = canvas.getContext("2d")!;
  let balls: Ball[] = [];
  let frames = 0;
  let paused = false;
  let raf = 0;
  let destroyed = false;

  function init() {
    balls = [];
    for (let i = 0; i < 5; i++) balls.push(randomBall());
    frames = 0;
  }

  function step() {
    for (const b of balls) {
      b.vy += G;
      b.x += b.vx;
      b.y += b.vy;
      if (b.x < R) { b.x = R; b.vx = Math.abs(b.vx); }
      if (b.x > W - R) { b.x = W - R; b.vx = -Math.abs(b.vx); }
      if (b.y < R) { b.y = R; b.vy = Math.abs(b.vy); }
      if (b.y > H - R) { b.y = H - R; b.vy = -Math.abs(b.vy); }
    }
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        const a = balls[i];
        const b = balls[j];
        let dx = b.x - a.x;
        let dy = b.y - a.y;
        let d = Math.sqrt(dx * dx + dy * dy);
        if (d >= 2 * R) continue;
        if (d === 0) { dx = 1; dy = 0; d = 1; }
        const nx = dx / d;
        const ny = dy / d;
        const overlap = 2 * R - d;
        a.x -= (nx * overlap) / 2;
        a.y -= (ny * overlap) / 2;
        b.x += (nx * overlap) / 2;
        b.y += (ny * overlap) / 2;
        for (const p of [a, b]) {
          p.x = Math.min(W - R, Math.max(R, p.x));
          p.y = Math.min(H - R, Math.max(R, p.y));
        }
        // solo intercambian si se acercan
        const rel = (b.vx - a.vx) * nx + (b.vy - a.vy) * ny;
        if (rel < 0) {
          const tx = a.vx, ty = a.vy;
          a.vx = b.vx; a.vy = b.vy;
          b.vx = tx; b.vy = ty;
        }
      }
    }
  }

  function draw() {
    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = "#f8fafc";
    ctx.fillRect(0, 0, W, H);
    ctx.fillStyle = "#e11d48";
    for (const b of balls) {
      ctx.beginPath();
      ctx.arc(b.x, b.y, R, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  function loop() {
    if (destroyed || paused) return;
    step();
    draw();
    frames++;
    onUpdate(balls.length, frames);
    raf = requestAnimationFrame(loop);
  }

  init();
  draw();
  onUpdate(balls.length, frames);
  raf = requestAnimationFrame(loop);

  return {
    add() {
      balls.push(randomBall());
      onUpdate(balls.length, frames);
      if (paused) draw();
    },
    pause() {
      paused = true;
      cancelAnimationFrame(raf);
    },
    resume() {
      if (!paused) return;
      paused = false;
      raf = requestAnimationFrame(loop);
    },
    reset() {
      cancelAnimationFrame(raf);
      init();
      draw();
      onUpdate(balls.length, frames);
      paused = false;
      raf = requestAnimationFrame(loop);
    },
    destroy() {
      destroyed = true;
      cancelAnimationFrame(raf);
    },
  };
}
